from pathlib import Path
import base64, hashlib, subprocess, sys, zlib

root = Path(sys.argv[1]).resolve()
payload = ""
patch = zlib.decompress(base64.b64decode(payload))
expected = "637e9af2580d893ea791ef5b7dce8091b41aac4936f48abcd5e26621e813c1d0"
actual = hashlib.sha256(patch).hexdigest()
if actual != expected:
    raise RuntimeError(f"alpha47 patch checksum mismatch: {actual} != {expected}")

subprocess.run(["git", "-C", str(root), "apply", "--whitespace=nowarn", "-"], input=patch, check=True)
print("PKVault V8 alpha47 Archivist Magearna reward and permanent-tab filter layout applied")
